class Solution {
    public int numPermsDISequence(String s){
        long mod=1000000007L;
        long[] dp={
            1
        };
        for(char relation:s.toCharArray()){
            long[] next=new long[dp.length+1];
            if(relation=='I')for(int j=1;j<next.length;j++)next[j]=(next[j-1]+dp[j-1])%mod;
            else for(int j=dp.length-1;j>=0;j--)next[j]=(next[j+1]+dp[j])%mod;
            dp=next;
        }
        long answer=0;
        for(long value:dp)answer=(answer+value)%mod;
        return(int)answer;
    }
}

code.kotlin:
class Solution {
    fun numPermsDISequence(s:String):Int{
        val mod=1000000007L;
        var dp=longArrayOf(1);
        for(relation in s){
            val next=LongArray(dp.size+1);
            if(relation=='I')for(j in 1 until next.size)next[j]=(next[j-1]+dp[j-1])%mod else for(j in dp.lastIndex downTo 0)next[j]=(next[j+1]+dp[j])%mod;
            dp=next
        };
        return(dp.fold(0L){
            sum,value->(sum+value)%mod
        }).toInt()
    }
}

code.cpp:
class Solution {
    public: int numPermsDISequence(string s){
        const long long mod=1000000007;
        vector<long long> dp{
            1
        };
        for(char relation:s){
            vector<long long> next(dp.size()+1);
            if(relation=='I')for(int j=1;j<(int)next.size();++j)next[j]=(next[j-1]+dp[j-1])%mod;
            else for(int j=dp.size()-1;j>=0;--j)next[j]=(next[j+1]+dp[j])%mod;
            dp.swap(next);
        }
        return accumulate(dp.begin(),dp.end(),0LL)%mod;
    }
};
